        static readonly int[] Positions={3,4,6,5,7,0,8,9,2,1};
        static bool CanDropBase(IDataObject data)
        {if(data==null||!data.GetDataPresent(DataFormats.FileDrop))return false;var paths=data.GetData(DataFormats.FileDrop) as string[];return paths!=null&&paths.Length==1&&File.Exists(paths[0])&&new[]{".png",".jpg",".jpeg",".bmp",".gif"}.Contains(Path.GetExtension(paths[0]).ToLowerInvariant());}
        async Task LoadDroppedBase(IDataObject data)
        {if(Busy)return;if(!CanDropBase(data)){Status.Text=L.T("请拖入一张 PNG、JPG、BMP 或 GIF 图片作为底图。");return;}await LoadBaseImage(((string[])data.GetData(DataFormats.FileDrop))[0]);}
        async Task PickBaseImage()
        {
            if(Busy)return;
#if SELF_TEST
            if(testBasePicker!=null){string selected=testBasePicker();if(selected!=null)await LoadBaseImage(selected);return;}
#endif
            using(var dialog=new OpenFileDialog{Filter="图片|*.png;*.jpg;*.jpeg;*.bmp;*.gif"})if(L.Show(dialog,FindForm())==DialogResult.OK)await LoadBaseImage(dialog.FileName);
        }
        void ClearPreview()
        {
            if(Busy)return;ticket++;debounce.Stop();again=false;previewCleared=true;completed=null;imagePath=null;source.Text=L.T("尚未选择图片");view.Image=null;view.PlacementRegion=RectangleF.Empty;if(preview!=null){preview.Dispose();preview=null;}ClearAiResult();Status.Text=L.T("预览已清空，二维码内容、模型和文字设置已保留。");
        }
        async Task LoadBaseImage(string path)
        {
            if(Busy)return;await Run(async token=>{string full=Path.GetFullPath(path);await Task.Run(()=>{token.ThrowIfCancellationRequested();using(var check=Codec.Load(full)){token.ThrowIfCancellationRequested();}},token);ClearAiResult();previewCleared=false;imagePath=full;source.Text=Path.GetFileName(full);completed=null;if(mode.SelectedIndex==0)mode.SelectedIndex=1;return L.T("底图已载入，原图保持完整。");},false);Schedule();
        }
        static SoftCombo Combo(int width,params string[] values){var c=new SoftCombo{Width=width,VisibleRows=3};c.Items.AddRange(values);c.SelectedIndex=0;return c;}
        void LoadLayer(CoverTextOptions t){loading=true;try{words.Text=t.Text;position.SelectedIndex=Array.IndexOf(Positions,t.Position);font.Value=t.SizePercent;tx.Value=t.X;ty.Value=t.Y;}finally{loading=false;}Schedule();}
        void ChangeText(){if(loading)return;previewCleared=false;aiTerminalStatus=null;bool overlay=mode.SelectedIndex!=0;artInfo.Visible=mode.SelectedIndex==2;UpdateAiMode();size.Enabled=x.Enabled=y.Enabled=placement.Enabled=words.Enabled=position.Enabled=font.Enabled=layers.Enabled=overlay;view.TextPlacement=overlay&&!(mode.SelectedIndex==3&&aiPlace.Checked);var t=layers.Active;t.Text=words.Text;layers.RefreshNames();t.Position=Positions[position.SelectedIndex];t.SizePercent=(int)font.Value;t.X=(int)tx.Value;t.Y=(int)ty.Value;tx.Enabled=ty.Enabled=overlay&&t.Position==3;Schedule();}
        void Schedule(){ticket++;if(!IsDisposed){if(view.PlacementDragging){debounce.Interval=25;if(!debounce.Enabled)debounce.Start();}else{debounce.Stop();debounce.Start();}}}
        Bitmap Generate(string path,string link,int percent,int px,int py,int margin,CoverTextOptions options,out QrRegion region,int bound=0,bool artistic=false,System.Threading.CancellationToken token=default(System.Threading.CancellationToken),bool rawPayload=false){using(var image=path==null?null:Codec.Load(path)){if(image==null||bound==0)return artistic?QrArt.Compose(image,link,percent,px,py,options,out region,margin,token,rawPayload):QrService.Compose(image,link,1024,percent,px,py,options,out region,margin,rawPayload);var dims=Codec.OutputSize(image,bound);using(var small=Codec.Fit(image,dims.Width,dims.Height,Color.White))return artistic?QrArt.Compose(small,link,percent,px,py,options,out region,margin,token,rawPayload):QrService.Compose(small,link,1024,percent,px,py,options,out region,margin,rawPayload);}}
        string CurrentPayload(){return raw.Checked&&importedPayload!=null&&url.Text==importedDisplay?importedPayload:url.Text;}
        string PreviewKey(){return (mode.SelectedIndex==3?AiGenerationKey():"")+"|"+mode.SelectedIndex+"|"+imagePath+"|"+(imagePath!=null&&File.Exists(imagePath)?File.GetLastWriteTimeUtc(imagePath).Ticks.ToString():"")+"|"+CurrentPayload()+"|"+raw.Checked+"|"+border.Value+"|"+size.Value+"|"+x.Value+"|"+y.Value+"|"+Inspection.Json().Serialize(text);}
        async Task Preview(){if(Busy||previewCleared)return;if(calculating){again=true;return;}string key=PreviewKey();if(preview!=null&&key==completed)return;calculating=true;int version=ticket;bool artistic=mode.SelectedIndex==2,rawPayload=raw.Checked;string path=mode.SelectedIndex==0?null:imagePath,link=CurrentPayload();int percent=(int)size.Value,px=(int)x.Value,py=(int)y.Value,margin=(int)border.Value;var options=text.Copy();Bitmap next=null;try{if(mode.SelectedIndex==3){ShowAiPreview();return;}if(mode.SelectedIndex!=0&&path==null)throw new ArgumentException("请先选择底图。");next=await Task.Run(()=>{QrRegion r;using(var full=Generate(path,link,percent,px,py,margin,options,out r,1200,artistic,System.Threading.CancellationToken.None,rawPayload))return Codec.Fit(full,Math.Max(1,(int)(full.Width*Math.Min(1,900.0/Math.Max(full.Width,full.Height)))),Math.Max(1,(int)(full.Height*Math.Min(1,900.0/Math.Max(full.Width,full.Height)))),Color.White);});if(version!=ticket||IsDisposed)return;view.Image=next;if(preview!=null)preview.Dispose();preview=next;next=null;completed=key;Status.Text=L.T("拖动预览可调整二维码或当前文字的位置。");}catch(Exception e){if(version==ticket&&!IsDisposed)Status.Text=L.T(e.Message);}finally{if(next!=null)next.Dispose();calculating=false;if(again&&!IsDisposed){again=false;Schedule();}}}
