        async Task Scan(string path){await Run(async token=>{string[] candidates=await Task.Run(()=>{using(var b=Codec.Load(path))return QrService.ScanAll(b,token);},token);token.ThrowIfCancellationRequested();if(candidates.Length==0){SetResult(null);return L.T(ImportMissing);}string found=ChooseQrContent(candidates);token.ThrowIfCancellationRequested();if(found==null)return L.T("已取消二维码导入。");SetResult(found);return L.T("扫描完成，请核对网站后打开。");},false);}
        void PasteUrl(string value){if(!raw.Checked)value=(value??"").Trim();if(string.IsNullOrWhiteSpace(value)){Status.Text=L.T("剪贴板中没有文字网址。");return;}if(value.Length>url.MaxLength){Status.Text=L.T("剪贴板内容过长，请粘贴单个网址。");return;}importedPayload=importedDisplay=null;url.Text=value;url.FocusText();}
        void SetResult(string value){decoded=value;result.Text=value??L.T("未发现二维码，请导入清晰原图。");open.Enabled=false;try{string target=QrService.Website(value);result.Text=new Uri(target).Host+"\n"+value;open.Enabled=true;}catch(ArgumentException){} }
