        public override void OnEnterPage(){base.OnEnterPage();Schedule();}
        protected override void Dispose(bool disposing){if(disposing){ticket++;debounce.Stop();debounce.Dispose();view.Image=null;if(preview!=null)preview.Dispose();DisposeAi();}base.Dispose(disposing);}
